namespace PsychologyApp.Application.Articles;

public static partial class ArticleContent
{
    private static readonly Article[] AdditionalArticlesEs =
    [
        MiniArticle(ArticleIds.CallNerves, "Nervios antes de una llamada", "Haz que la primera llamada sea más sencilla", "No ensayes toda la conversación. Anota un objetivo y una frase para empezar. Durante la llamada puedes mirar tu nota, pedir que repitan algo o hacer una pausa. Hacer la llamada ya cuenta como éxito, aunque no hables perfectamente."),
        MiniArticle(ArticleIds.WaitingForReply, "Esperar una respuesta", "El silencio en el chat no explica nada", "Anota tres posibles motivos, incluido uno neutral, y elige cuándo volver a revisar. Si es urgente, decide a quién contactar y cuándo en vez de actualizar la pantalla una y otra vez."),
        MiniArticle(ArticleIds.AfterSocialEvent, "Después de una reunión: deja de repasar cada frase", "Interrumpe la repetición mental de la conversación", "Nombra un momento que salió bien y una conclusión que todavía no puedes sacar. No busques la frase perfecta a posteriori. Vuelve a lo que haces ahora; más tarde podrás retomar una conversación importante."),
        MiniArticle(ArticleIds.FearOfMistakes, "Un error no es una sentencia", "Define qué significa suficientemente bien", "Antes de empezar, decide qué resultado basta y revisa un requisito importante. Si hay un error, averigua sus consecuencias reales y el siguiente paso que puedes corregir. Un fallo no te define por completo."),
        MiniArticle(ArticleIds.ChangeAnxiety, "Cuando los cambios preocupan", "Separa los hechos de lo que aún no sabes", "Haz dos columnas: lo que ya sabes y lo que podrías averiguar. Elige una pregunta y un momento para retomarla. Lo demás puede esperar; la incertidumbre no significa que vaya a ocurrir algo malo."),
        MiniArticle(ArticleIds.WorryBeforeTask, "Antes de una tarea difícil", "Empieza sin exigir plena confianza", "Decide qué necesitas para empezar de forma segura: materiales, diez minutos o una aclaración. Empieza solo por eso y luego decide si continúas. No hace falta esperar a que desaparezca la ansiedad."),
        MiniArticle(ArticleIds.AvoidedFirstStep, "Da solo el primer paso", "Empezar puede llevar dos minutos", "Haz pequeño el comienzo: abre el archivo, escribe un título o prepara los materiales. Después puedes parar. El objetivo es facilitar el inicio, no quitarte el derecho a descansar."),
        MiniArticle(ArticleIds.CheckingLoop, "Revisa y después para", "Pon un límite antes de revisar", "Decide qué revisarás y cuántas veces. Tras la última revisión, márcala como terminada y cambia de actividad. Si la ansiedad pide otra, reconócelo como una petición de la ansiedad, no como un dato nuevo."),
        MiniArticle(ArticleIds.PublicPlaceAnxiety, "Ansiedad en un lugar público", "Encuentra un apoyo y conserva la posibilidad de elegir", "Siente el suelo bajo los pies y nombra algunos objetos a tu alrededor. Busca un lugar tranquilo. Puedes irte o pedir ayuda si no estás a salvo; ningún ejercicio debe obligarte a quedarte."),
        MiniArticle(ArticleIds.MorningWorry, "Una mañana sin lista de preocupaciones", "No tienes que resolver la semana antes del desayuno", "Anota tus preocupaciones y marca una necesidad real para hoy. Programa el resto o espera a tener información nueva. Empieza con un paso, no intentando preverlo todo."),
        MiniArticle(ArticleIds.SensoryOverload, "Cuando hay demasiado ruido y actividad", "Reduce la carga sobre tu atención", "Si puedes, quita una fuente de ruido, baja el brillo o ve a un sitio más tranquilo. Elige un punto de apoyo para la atención. Una pausa no te obliga a volver enseguida al ritmo anterior."),
        MiniArticle(ArticleIds.EveningTension, "Termina el día con suavidad", "Pasa las tareas pendientes a mañana", "Dedica unos minutos a anotar qué terminaste, qué puede esperar y por dónde empezarás mañana. Si la rutina cambió, elige una señal sencilla para acostarte en vez de un ritual estricto."),
        MiniArticle(ArticleIds.AnxietyComedown, "Después de una subida de ansiedad", "Recupérate primero y reflexiona después", "Comprueba que estás a salvo y date tiempo para volver a tu propio ritmo. Puede ayudar una actividad sencilla y conocida. Más tarde anota qué te ayudó y qué te gustaría hablar con un profesional."),
        MiniArticle(ArticleIds.SafePractice, "Una práctica no es un examen", "Adapta el ejercicio a ti", "Puedes acortarlo, dejar los ojos abiertos, saltarte un paso o parar. Si resulta incómodo, vuelve a respirar con naturalidad y elige otro apoyo. No tienes que aguantar malestar para seguir una instrucción."),

        MiniArticle(ArticleIds.ThoughtLabel, "Ponle nombre al pensamiento", "Obsérvalo sin discutir con él", "Prueba: «Estoy notando el pensamiento de que…». No demuestra que sea falso; ayuda a verlo como un pensamiento. Después pregúntate qué acción pequeña encaja ahora con tu tarea o tus valores."),
        MiniArticle(ArticleIds.MindReading, "No adivines lo que piensan los demás", "Separa lo que observaste de lo que supones", "Anota lo que la persona dijo o hizo literalmente y luego lo que interpretaste. Si la respuesta importa, pregunta con calma y claridad. Si no, deja la duda abierta en vez de tratar una suposición como un hecho."),
        MiniArticle(ArticleIds.WorstVsLikely, "Lo peor no es lo más probable", "Haz sitio para varias posibilidades", "Anota el peor resultado, el mejor y el más plausible. Prepárate para el más plausible; para el peor, basta un plan de seguridad razonable si hace falta. No gastes toda tu energía en cada escenario imaginado."),
        MiniArticle(ArticleIds.EvidenceAndUnknown, "Lo que sé y lo que todavía no", "No llenes un vacío con una suposición ansiosa", "Haz dos columnas: «Lo sé» y «Aún no lo sé». Para lo desconocido, elige cómo obtener información o cuándo volver a revisarlo. Si ahora no puedes averiguarlo, deja la pregunta abierta."),
        MiniArticle(ArticleIds.NegativityFilter, "Fíjate también en lo que salió bien", "Añade otro dato a la imagen", "Después de algo difícil, la mente puede ver los errores y pasar por alto lo normal o lo bueno. Nombra un hecho que no encaje con la versión negativa. No tienes que fingir que todo va bien; basta con ver el conjunto."),
        MiniArticle(ArticleIds.ConversationReplay, "Deja de repetir la conversación sin parar", "Decide si hay un siguiente paso", "Pregúntate si existe un problema concreto que puedas reparar. Si sí, anota un paso breve. Si no, reconoce que es una repetición y vuelve a lo que ves, oyes o haces ahora."),
        MiniArticle(ArticleIds.DecisionFatigue, "Simplifica una decisión pequeña", "Decide de antemano qué es suficiente", "Para decisiones pequeñas que se repiten, usa una regla sencilla: presupuesto, tiempo o un criterio de calidad. Aplícala sin comparar todas las opciones para siempre. Reserva tiempo y datos aparte para decisiones importantes."),
        MiniArticle(ArticleIds.GoodEnough, "Suficientemente bien también es un resultado", "Limita los retoques innecesarios", "Nombra dos requisitos que debe cumplir el resultado y una hora para parar. Cuando se cumplan, guárdalo o envíalo. Haz más cambios solo para corregir un problema concreto, no para perseguir la perfección imposible."),
        MiniArticle(ArticleIds.ControlInfluence, "Lo que puedo influir y lo que no", "Enfócate en una acción disponible", "Dibuja dos círculos: lo que depende de ti y lo que no. Elige un paso dentro del primero; para el otro, considera un límite, apoyo o aceptar la incertidumbre. Esto no borra las injusticias ni las limitaciones reales."),
        MiniArticle(ArticleIds.SelfTalkReset, "Cambia el tono de tu diálogo interno", "Háblate con respeto y de forma concreta", "Cambia «lo he arruinado todo otra vez» por una acción: «No llegué al plazo; preguntaré qué se puede corregir». No excusa el error, pero ayuda a avanzar sin insultarte."),
        MiniArticle(ArticleIds.WorryAboutWorry, "Preocuparte por estar preocupado", "No te exijas calmarte enseguida", "Cuando pienses «no debería sentir esto», llámalo una segunda ola de preocupación. Deja que esté la primera reacción y vuelve a la tarea más cercana. Si la ansiedad interfiere a menudo, habla con un profesional."),
        MiniArticle(ArticleIds.CompareHighlightReel, "No compares tu vida con el escaparate de otra persona", "Una publicación muestra momentos elegidos, no una vida entera", "Recuerda que una publicación es solo un fragmento. Si la comparación empeora tu ánimo, pausa la red y elige tu propio referente: lo que te importa, no lo que parece impresionante."),
        MiniArticle(ArticleIds.IntrusiveThoughts, "Un pensamiento no deseado no es una intención", "Mira las acciones y el contexto, no solo el pensamiento", "Un pensamiento inquietante puede asustar porque no coincide con lo que quieres. No hace falta que te compruebes una y otra vez. Obsérvalo y vuelve a tu tarea; si interfiere mucho, busca apoyo profesional."),
        MiniArticle(ArticleIds.OneThingAtATime, "Una tarea cada vez", "Reduce el coste de cambiar de actividad", "Anota lo que requiere atención y elige una tarea para un rato breve. Cierra otras pestañas o avisos si puedes. Las demás tareas no desaparecen: esperan su turno en la lista."),

        MiniArticle(ArticleIds.MoodMovement, "Un poco de movimiento cuando falta energía", "La acción no tiene que esperar a que mejore el ánimo", "Elige un movimiento accesible por un par de minutos: estirarte, caminar por la habitación o mirar afuera. Observa cómo te sientes después. Es un experimento, no una obligación de hacer ejercicio o sentirte mejor."),
        MiniArticle(ArticleIds.PleasureMastery, "Disfrute y sensación de haber terminado", "Fíjate en distintos tipos de actividades que ayudan", "Puedes planear una actividad agradable y una tarea pequeña que dé sensación de cierre. Pueden ser la misma. Si no se hace, es información sobre tu carga, no una razón para culparte."),
        MiniArticle(ArticleIds.EnergyBudget, "Distribuye la energía, no solo el tiempo", "Deja espacio para recuperarte", "Marca las tareas que requieren más energía. Si es posible, pon una pausa corta o una tarea más ligera entre ellas. Un plan con margen suele ser más realista que una agenda sin descansos."),
        MiniArticle(ArticleIds.RestBreak, "Descansa sin sentir culpa", "El descanso puede ayudarte a elegir lo siguiente", "Elige una pausa breve y algo que te resulte reparador: silencio, agua, estirar o mirar a lo lejos. No conviertas la pausa en otra obligación. Si la carga no deja descansar, la disciplina no es el único problema."),
        MiniArticle(ArticleIds.StartFriction, "Quita un obstáculo antes de empezar", "Prepara el inicio con antelación", "Fíjate en qué suele impedir empezar: buscar un archivo, demasiados pasos o una tarea poco clara. Prepara solo lo siguiente: abre el documento, coloca el material o escribe la primera pregunta."),
        MiniArticle(ArticleIds.TransitionRitual, "Cambia de una tarea a otra", "Una pausa breve aclara el siguiente paso", "Antes de una tarea nueva, para un minuto: cierra el archivo anterior, anota lo pendiente y nombra lo siguiente. No es un ritual obligatorio ni una forma de producir más a toda costa, solo una transición clara."),
        MiniArticle(ArticleIds.TaskActivation, "Cuando cuesta empezar", "La acción puede llegar antes que la motivación", "Elige una acción visible que dure menos de cinco minutos; usa un temporizador solo si ayuda. Cuando termine, decide si continúas. La motivación puede aparecer después, pero no tienes que forzarte."),
        MiniArticle(ArticleIds.GentleRoutine, "Una rutina flexible, no perfecta", "Conserva un punto estable durante el día", "Elige una señal pequeña y repetible, como planear después del desayuno. Si cambia la hora, conserva el orden y no el minuto exacto. Saltarte un día no impide retomar el hábito."),
        MiniArticle(ArticleIds.WakeAtNight, "Si te despiertas durante la noche", "Mantén la calma y evita mirar el reloj", "Intenta no evaluar la noche minuto a minuto. Si estar en la cama resulta desagradable, puedes hacer una actividad tranquila con luz tenue y volver cuando tengas sueño. Si el problema persiste, coméntalo con un profesional sanitario."),
        MiniArticle(ArticleIds.SmallDayPlan, "Un plan diario con margen", "Elige lo principal y deja espacio para imprevistos", "Anota una tarea importante, una pequeña y una pausa. Lo demás es opcional si alcanza el tiempo y la energía. Puedes cambiar el plan; ser flexible no significa fallarte."),
        MiniArticle(ArticleIds.AskForHelpTask, "Pide ayuda con una parte concreta", "Una petición clara deja menos lugar a las suposiciones", "En vez de «ayúdame», indica una acción y un plazo: «¿Puedes revisar este párrafo hoy?» Añade qué resultado sería útil. Así es más fácil responder y saber si la ayuda encaja."),
        MiniArticle(ArticleIds.MeaningfulActivity, "Una actividad que te importa", "Conecta un paso pequeño con un valor", "Pregúntate qué importa aquí: cuidar, tener curiosidad, cumplir o descansar. Elige una acción pequeña en esa dirección. No necesita cambiar toda la situación para tener sentido."),
        MiniArticle(ArticleIds.FlexibleGoals, "Cambia el plan sin abandonar el objetivo", "Adapta el paso a la energía de hoy", "Si el plan original es demasiado grande, reduce la cantidad o cambia el método. Conserva la dirección, no necesariamente la forma: diez minutos en vez de una hora, o un borrador en vez de algo perfecto. La meta puede ser flexible."),
        MiniArticle(ArticleIds.CelebrateCompletion, "Reconoce lo que ya hiciste", "La mente suele saltar a la siguiente tarea", "Al terminar, nombra brevemente qué hiciste y cuánto esfuerzo te llevó. No necesitas una recompensa; basta con reconocerlo. Así ves también lo terminado, no solo lo pendiente."),

        MiniArticle(ArticleIds.NameEmotion, "Nombra la emoción con más precisión", "Una palabra puede ayudarte a responder", "En vez de «me siento mal», prueba una palabra más concreta: tensión, decepción, miedo o cansancio. Puedes no estar seguro; no es una prueba. Luego pregúntate qué necesitas: seguridad, pausa, claridad o contacto."),
        MiniArticle(ArticleIds.MixedFeelings, "Puedes sentir dos cosas distintas a la vez", "Tener sentimientos mezclados no te hace incoherente", "Puedes alegrarte por un cambio y echar de menos lo anterior. Nombra ambas partes sin obligarte a elegir. Pregunta cuál necesita atención ahora y ofrécele un pequeño gesto de cuidado."),
        MiniArticle(ArticleIds.AngerPause, "Haz una pausa antes de responder con ira", "Primero la seguridad, después las palabras", "Si la conversación se intensifica, propón una pausa y di cuándo podrías retomarla. Ve a un lugar seguro y date tiempo. Si existe riesgo de violencia, busca protección y ayuda."),
        MiniArticle(ArticleIds.ShameKindness, "Responde a la vergüenza sin humillarte", "Puedes reparar un error sin castigarte", "Dite: «Ahora siento vergüenza, pero este sentimiento no me describe por completo». Separa la acción de tu identidad: qué pasó y si algo puede repararse. Elige la respuesta que ofrecerías a alguien cercano."),
        MiniArticle(ArticleIds.GuiltRepair, "Culpa: reparar algo o dejarla ir", "Separa la responsabilidad del reproche interminable", "Si hiciste daño, piensa en una reparación concreta y una disculpa respetuosa. Si no hubo una falta real, la culpa puede ser un sentimiento, no una prueba. En cualquier caso, castigarte sin fin no ayuda a quien sufrió."),
        MiniArticle(ArticleIds.EnvyInformation, "La envidia puede señalar lo que deseas", "Convierte la comparación en una dirección propia", "Pregúntate qué envidias: libertad, reconocimiento, cercanía o habilidad. Eso no te hace mala persona. Da un pequeño paso hacia esa necesidad sin copiar la vida de otra persona ni despreciar tu camino."),
        MiniArticle(ArticleIds.AllowSadness, "La tristeza no tiene que desaparecer enseguida", "Dale espacio y elige un apoyo", "Nombra la pérdida o decepción sin obligarte a animarte. Pregúntate qué sería amable ahora: estar a solas, escribir a alguien o hacer una tarea pequeña. Si interfiere en tu vida durante mucho tiempo, busca ayuda."),
        MiniArticle(ArticleIds.Numbness, "Cuando cuesta sentir algo", "No te obligues a abrirte enseguida", "La sensación de estar entumecido puede aparecer con la sobrecarga, pero no explica por sí sola la causa. Empieza por algo neutral: dónde estás, qué ves y qué quieres en los próximos diez minutos. Si te preocupa o persiste, habla con un profesional."),
        MiniArticle(ArticleIds.EmotionWave, "Una emoción puede cambiar, aunque no enseguida", "Obsérvala sin cronómetro", "Valora la intensidad de cero a diez y nombra la emoción. Puedes volver a comprobarlo más tarde sin exigir que baje. La meta es notar cambios y conservar opciones, no medir cuánto tardas en calmarte."),
        MiniArticle(ArticleIds.BodyNoticingChoice, "Observa tu cuerpo a un ritmo cómodo", "También puedes elegir un apoyo externo", "Si notar las sensaciones corporales resulta desagradable, no te fuerces. Mira un objeto estable, siente la silla o nombra los sonidos. Prestar atención al cuerpo es una opción, no un requisito de la autoayuda."),
        MiniArticle(ArticleIds.PauseBeforeReact, "Haz una pausa entre el impulso y la acción", "Elige una respuesta que quizá lamentes menos", "Si quieres enviar un mensaje ya, espera unos minutos si es seguro. Nombra el objetivo y deja solo las palabras necesarias. Si esperar puede perjudicarte, actúa: la pausa debe ayudar, no estorbar."),
        MiniArticle(ArticleIds.EmotionalBoundary, "No te toca arreglar los sentimientos de otras personas", "Puedes acompañar y mantener tus límites", "Puedes escuchar sin aceptar todo ni prometer resolver el problema. Pregunta si la persona quiere apoyo o consejos y di qué puedes ofrecer. La empatía no exige renunciar a tus propias necesidades."),
        MiniArticle(ArticleIds.FeelingNotAction, "Un sentimiento no obliga a actuar", "Hay una elección entre emoción y conducta", "Puedes enfadarte sin insultar, tener miedo y pedir una pausa o sentir celos sin revisar mensajes. Nombra el impulso y elige una acción que tenga en cuenta lo que sientes y la seguridad de los demás."),
        MiniArticle(ArticleIds.AfterCrying, "Después de llorar", "Cuida el próximo minuto", "Puedes lavarte la cara, sentarte en silencio, respirar con normalidad, pedir agua o contactar con alguien cercano. No tienes que explicar las lágrimas enseguida. Si estás en peligro o no puedes mantenerte a salvo, pide ayuda urgente."),

        MiniArticle(ArticleIds.SpecificRequest, "Pide algo concreto", "Una petición clara deja espacio para responder", "Di qué pasó, qué necesitas y para cuándo. Por ejemplo: «No llego a preparar el material; ¿puedes encargarte de esta parte antes del viernes?» La otra persona puede decir que no; puedes buscar otra opción."),
        MiniArticle(ArticleIds.ListenReflect, "Primero comprende y después responde", "Una breve comprobación puede reducir la tensión", "Repite con tus palabras lo que entendiste y pregunta si es correcto. No des consejos si no te los han pedido. Aunque no estés de acuerdo, puedes mostrar que escuchaste el mensaje."),
        MiniArticle(ArticleIds.BoundarySentence, "Una frase para marcar un límite", "Una respuesta breve suele ser más clara que una defensa larga", "Prueba: «Ahora no puedo encargarme de esto» o «Ese tono no me va bien; seguimos cuando podamos hablar con calma». Adapta la frase a tu situación y seguridad. Un límite dice lo que tú harás, no lo que debe hacer otra persona."),
        MiniArticle(ArticleIds.NoWithoutEssay, "Puedes decir que no sin dar una explicación larga", "Elige una frase amable y clara", "Puedes decir «Gracias, pero no puedo» o «No me viene bien». Ofrece una alternativa solo si quieres. En una situación insegura, una negativa directa quizá no sea lo mejor; elige lo que te proteja."),
        MiniArticle(ArticleIds.DifficultTalkOpening, "Empieza una conversación difícil con un objetivo", "Habla de un episodio y una petición", "Elige un momento tranquilo, nombra una situación concreta y di qué te gustaría cambiar. Por ejemplo: «Me cuesta cuando los planes cambian sin avisar; ¿podemos avisarnos antes?» No empieces si hacerlo no es seguro."),
        MiniArticle(ArticleIds.RepairAfterConflict, "Retoma la conversación después de una discusión", "Da un pequeño paso hacia la claridad", "Cuando ambos estén preparados, nombra tu parte y pregunta cómo vio la situación la otra persona. No hace falta resolver todos los desacuerdos de golpe. Si vuelve a ser inseguro, para y busca apoyo."),
        MiniArticle(ArticleIds.ApologyResponsibility, "Discúlpate sin renunciar a tus límites", "Nombra la acción y lo que cambiarás", "Una disculpa útil es concreta: «Te interrumpí; la próxima vez escucharé». No añadas «pero tú…» en la misma frase. Reconocer un error no significa aceptar toda acusación ni renunciar a tu seguridad."),
        MiniArticle(ArticleIds.FeedbackAsInformation, "Separa una crítica de tu valor", "Aclara qué puedes aprovechar", "Busca la acción concreta que puedes cambiar y pide un ejemplo si no está clara. Un resultado no juzga toda tu persona. Los insultos no se convierten en comentarios útiles por llamarlos críticas."),
        MiniArticle(ArticleIds.ReceiveNo, "Cuando alguien te dice que no", "Rechazar una petición no siempre es rechazarte", "Separa la respuesta a una petición concreta de lo que concluyes sobre ti. Si encaja, pregunta por otro momento u opción. Puedes sentir decepción y buscar apoyo en otro lugar."),
        MiniArticle(ArticleIds.CheckAssumption, "Comprueba una suposición con una pregunta", "Aclara el sentido antes de construir una historia", "Si un mensaje es ambiguo, pregunta con neutralidad: «¿Entendí bien que…?» Es más útil que responder a un supuesto doble sentido. Si no puedes preguntar, separa el hecho de la interpretación y espera antes de concluir."),
        MiniArticle(ArticleIds.AskSupport, "Pedir apoyo es una habilidad", "Di qué te ayudaría", "Puedes pedir que te escuchen, caminar juntos o ayudar con una tarea concreta. Aclara si quieres ideas o solo compañía. Si alguien no puede ayudar, eso no demuestra que tus necesidades sean excesivas."),
        MiniArticle(ArticleIds.SupportWithoutFixing, "Acompaña sin arreglarlo todo", "Pregunta qué tipo de apoyo hace falta", "Prueba: «¿Quieres que te escuche, que me quede contigo o que pensemos en el siguiente paso?» No prometas lo que no puedes cumplir. El apoyo respeta las decisiones de la otra persona y tus límites."),
        MiniArticle(ArticleIds.ConflictNotFailure, "Un desacuerdo no siempre significa que la relación terminó", "Fíjate en cómo se tratan", "También importan el respeto, poder hacer una pausa y hablar de las consecuencias. No tienes que aceptar amenazas o violencia para «salvar la relación»; la seguridad va primero."),
        MiniArticle(ArticleIds.MakeExpectationsClear, "Expresa las expectativas con antelación", "No esperes que la otra persona lo adivine", "Antes de hacer algo juntos, aclara plazos, funciones y qué significa terminar. Comprueba que entendisteis el acuerdo igual. La claridad no garantiza el acuerdo, pero muestra las diferencias antes."),
        MiniArticle(ArticleIds.DigitalBoundaries, "Límites en los mensajes", "Las notificaciones no tienen que dirigir tu día", "Elige cuándo responder y desactiva avisos no esenciales si te conviene. Puedes contar a la gente cercana cuándo sueles estar disponible. Conserva otro modo claro de contacto para urgencias."),
        MiniArticle(ArticleIds.FamilyPressure, "Cuando la familia insiste con sus consejos", "Agradece y di que decidirás", "Prueba: «Veo que te preocupa. Lo pensaré y decidiré». Si la conversación continúa, repite la frase o cambia de tema. Usa esta forma solo si no aumenta el riesgo para ti."),
        MiniArticle(ArticleIds.FriendshipInvitation, "Invita a alguien sin organizar un gran plan", "Una invitación pequeña es más fácil de aceptar o rechazar", "Propón algo concreto y sin presión: «¿Te apetece pasear el jueves después del trabajo?» Añade que otro momento o un no están bien. La respuesta habla de su disponibilidad ahora, no de tu valor."),
        MiniArticle(ArticleIds.SmallConnection, "Un contacto pequeño también cuenta", "No tienes que empezar con una conversación profunda", "Si te sientes solo, elige una forma fácil de estar con gente: un mensaje breve, un sitio conocido o una charla neutral. Para cuando sea suficiente. El objetivo es probar conexión, no obligarte a socializar."),

        MiniArticle(ArticleIds.OrientNow, "Comprueba dónde estás ahora", "Una forma suave de orientarte al presente", "Mira alrededor y nombra el lugar, la fecha o el momento del día, algunos objetos y lo que ocurre ahora. Mantén los ojos abiertos y ve a tu ritmo. Si aumenta la ansiedad, elige un objeto neutral o pide apoyo."),
        MiniArticle(ArticleIds.GroundingChoice, "Elige un anclaje que te venga bien", "No a todo el mundo le resulta cómodo enfocarse en el cuerpo", "Puedes nombrar colores, describir un objeto, notar la silla o escuchar un sonido constante. Elige algo tolerable ahora. Si te hace sentir peor, para y prueba otra cosa."),
        MiniArticle(ArticleIds.AfterNightmare, "Después de una pesadilla", "Recuerda que el sueño ya terminó", "Enciende una luz suave, mira alrededor y nombra señales de que estás en tu habitación. No tienes que recordar el sueño en detalle. Si las pesadillas se repiten o alteran el sueño, coméntalo con un profesional sanitario."),
        MiniArticle(ArticleIds.AnniversaryReaction, "Fechas difíciles y aniversarios", "La reacción puede llegar antes o después", "Si una fecha te recuerda un hecho difícil, deja menos tareas y elige apoyo con antelación. Puedes conmemorarla a tu manera o no hacerlo. Sentir mucho no significa volver al principio."),
        MiniArticle(ArticleIds.PaceRecovery, "Recupérate a tu propio ritmo", "No conviertas el autocuidado en una maratón", "Elige una práctica manejable y cuánto tiempo quieres dedicarle. Puedes parar o cambiar de método. Observa no solo el ánimo, sino también si te sientes más cómodo o seguro."),
        MiniArticle(ArticleIds.SafetyFirst, "La seguridad importa más que el ejercicio", "La autoayuda no exige quedarse en peligro", "Si hay una amenaza cerca, intenta llegar primero a un lugar más seguro y contactar con alguien que pueda ayudarte. Respirar o anclarte no sustituye la protección, la atención médica ni los servicios de emergencia."),
        MiniArticle(ArticleIds.ChooseTrustedPerson, "Elige a alguien a quien pedir apoyo", "Piensa en una persona a quien puedas escribir con sencillez", "Nombra a alguien que suele respetar tus límites. Prepara una frase: «Lo estoy pasando mal; ¿puedes seguir en contacto?» Si no hay nadie disponible, contacta con un profesional o un servicio local."),
        MiniArticle(ArticleIds.AfterStressRecovery, "Después de un evento estresante", "Date tiempo para volver a las tareas habituales", "Después de un día duro, elige una acción básica y otra tranquila: comer, cambiarte, sentarte en silencio o escribir a alguien. No te exijas explicar todo ni recuperar enseguida la productividad anterior."),
        MiniArticle(ArticleIds.FlashbackGrounding, "Cuando el pasado parece estar cerca otra vez", "Oriéntate al presente y conserva la capacidad de elegir", "Mira alrededor y nombra dónde estás y la fecha si ayuda. Elige un objeto visible o contacta con alguien cercano. No te obligues a cerrar los ojos, respirar hondo o contar detalles; si hay peligro, busca ayuda real."),
        MiniArticle(ArticleIds.RecoveryNotLinear, "La recuperación no es una línea recta", "Un día difícil no borra lo que has avanzado", "No te compares con una línea ascendente perfecta; mira qué te ayuda hoy. Las emociones fuertes pueden volver después de un periodo bueno. Si empeoras o cuesta manejarlo, puedes volver a pedir apoyo."),

        MiniArticle(ArticleIds.BreathIsOptional, "La práctica de respiración es opcional", "No te obligues a cambiar la respiración", "Si enfocarte en la respiración resulta desagradable, deja que siga natural y elige un apoyo externo: color, sonido u objeto. Estas prácticas no son adecuadas para todo el mundo y no sustituyen la atención ante falta de aire importante o síntomas nuevos."),
        MiniArticle(ArticleIds.GroundingCanChange, "Si el anclaje no ayuda", "Cambia de método o para", "Un ejercicio no tiene que funcionar siempre. Prueba un apoyo externo más simple, pide a alguien que describa la habitación o termina la práctica. Un intento difícil no significa que lo hayas hecho mal."),
        MiniArticle(ArticleIds.MovementAnchor, "Usa el movimiento como apoyo", "Un movimiento pequeño puede devolverte opciones", "Si es cómodo y seguro, abre y cierra las manos despacio o cambia el peso de un pie a otro. También puedes observar un objeto en movimiento. No fuerces si duele; elige un objeto quieto si te conviene más."),
        MiniArticle(ArticleIds.SensesAnchor, "Un apoyo a través de los sentidos", "Elige una señal neutral de tu entorno", "Nombra un color, la temperatura del aire o un sonido constante que no te moleste. No hace falta encontrar cinco cosas ni cerrar los ojos. Una señal neutral puede bastar; cambia si resulta desagradable."),
        MiniArticle(ArticleIds.EarlyStressSigns, "Observa las primeras señales de sobrecarga", "Notarlas antes te da más opciones", "Piensa qué cambia primero: el ritmo al hablar, la tensión, la atención o las ganas de cancelar todo. Anota esa señal y una respuesta amable: hacer una pausa, aclarar la tarea o pedir ayuda. Es una observación, no un diagnóstico."),
        MiniArticle(ArticleIds.RelaxWithoutForce, "Relájate sin forzarte", "No tienes que alcanzar una calma total", "Elige una acción que requiera poca concentración: bajar los hombros, acomodarte o aflojar las manos. Deja la respiración natural. Un poco de comodidad basta; no fuerces al cuerpo a relajarse por completo."),
        MiniArticle(ArticleIds.BasicCareWithoutRules, "Cuidados básicos sin reglas estrictas", "Elige lo que necesitas ahora", "Pregúntate qué te ayudaría durante la próxima hora: agua, comida, calor, silencio, movimiento o contacto. Elige solo lo que esté a tu alcance. Si no es posible, no te culpes; quizá falte ayuda o unas condiciones adecuadas."),
        MiniArticle(ArticleIds.NewSymptomsCare, "Síntomas nuevos o poco habituales", "No te diagnostiques con un artículo", "Si los síntomas físicos son nuevos, intensos o cambian rápidamente, consulta con un profesional sanitario. Ante señales de emergencia, llama a los servicios locales. Una práctica de autoayuda no debe retrasar una valoración médica."),
        MiniArticle(ArticleIds.FindTherapist, "Cómo buscar un profesional", "Busca una relación de trabajo adecuada, no una descripción perfecta", "Pregunta por la formación, la experiencia con tu tema, el formato, el coste y la confidencialidad. En la primera cita, pregunta cómo se trabajará y cómo sabrás si ayuda. Puedes buscar a otra persona si no encaja."),
        MiniArticle(ArticleIds.FirstAppointment, "La primera cita", "No necesitas preparar una historia perfecta", "Anota un par de temas importantes y preguntas sobre las sesiones. Puedes decir «me cuesta explicarlo» y empezar con un ejemplo de la última semana. Pide una pausa o pregunta qué será confidencial."),
        MiniArticle(ArticleIds.DescribeSymptoms, "Cómo describir lo que te pasa", "Un ejemplo real ayuda más que los términos perfectos", "Cuenta cuándo empezó, con qué frecuencia sucede y qué cambia en tu vida diaria. Si cuesta hablar, lleva una nota o enséñala. No tienes que adivinar un diagnóstico para pedir ayuda."),
        MiniArticle(ArticleIds.SelfHelpLimits, "Cuando la autoayuda no basta", "El apoyo profesional es un siguiente paso válido", "Si tu estado altera durante mucho tiempo el sueño, el trabajo, el estudio o el autocuidado, empeora o los ejercicios no ayudan, contacta con un profesional sanitario o psicólogo. No tienes que demostrar que ya lo resolviste por tu cuenta."),

        MiniArticle(ArticleIds.ScreeningNotDiagnosis, "Un cuestionario no es un diagnóstico", "El resultado puede iniciar una conversación, no ponerte una etiqueta", "Las respuestas reflejan un periodo concreto y dependen de las circunstancias. Enseña el resultado a un profesional si te preocupa. No cambies un tratamiento ni tomes decisiones importantes basándote solo en una puntuación."),
        MiniArticle(ArticleIds.SupportPlan, "Prepara un plan breve de apoyo", "Anota señales, pasos y contactos", "Escribe cómo notas que empeoras, qué suele ayudarte y a quién puedes avisar. Añade contactos profesionales y servicios locales de emergencia. El plan no sustituye la ayuda; indica a quién llamar cuando cuesta pensar."),
        MiniArticle(ArticleIds.CrisisSteps, "Si ahora mismo no estás a salvo", "Conecta con ayuda en tiempo real", "Ve a un lugar más seguro si es posible y contacta con emergencias locales o alguien de confianza. Di brevemente qué ocurre y dónde estás. No te quedes a solas si hay peligro inmediato."),
        MiniArticle(ArticleIds.MedicationWithClinician, "Consulta con un profesional las dudas sobre medicación", "No cambies una receta por tu cuenta", "Si te preocupa una medicación, anota el nombre, la pregunta y cualquier efecto no deseado y coméntalo con quien la recetó o con un farmacéutico. No empieces, suspendas ni cambies dosis basándote en una app o artículo."),
    ];
